import{_ as a,o,c as r,a0 as e}from"./chunks/framework.Caz7a20Z.js";const u=JSON.parse('{"title":"PPT 汇报完成！论文又改了一遍，主要去 AI 味","description":"PPT 汇报完成了，论文又改了一遍——主要是去除 AI 痕迹和重新通看，图也都重做了；明天的任务是通读一遍、改参考文献、理讨论的逻辑结构，完成才算改完。","frontmatter":{"title":"PPT 汇报完成！论文又改了一遍，主要去 AI 味","date":"2026-09-08T00:00:00.000Z","tags":["日记"],"description":"PPT 汇报完成了，论文又改了一遍——主要是去除 AI 痕迹和重新通看，图也都重做了；明天的任务是通读一遍、改参考文献、理讨论的逻辑结构，完成才算改完。"},"headers":[],"relativePath":"posts/diary-20260908.md","filePath":"posts/diary-20260908.md","lastUpdated":1788871744000}'),s={name:"posts/diary-20260908.md"};function n(p,t,i,l,d,h){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="ppt-汇报完成-论文又改了一遍-主要去-ai-味" tabindex="-1">PPT 汇报完成！论文又改了一遍，主要去 AI 味 <a class="header-anchor" href="#ppt-汇报完成-论文又改了一遍-主要去-ai-味" aria-label="Permalink to &quot;PPT 汇报完成！论文又改了一遍，主要去 AI 味&quot;">​</a></h1><p>今天两件大事落地，收工的时候心里挺踏实的 😌。</p><h2 id="ppt-汇报-完成了" tabindex="-1">PPT 汇报：完成了！ <a class="header-anchor" href="#ppt-汇报-完成了" aria-label="Permalink to &quot;PPT 汇报：完成了！&quot;">​</a></h2><p>先说最要紧的：<strong>PPT 汇报完成了</strong> ✅！</p><p>前天晚上还在那儿紧张&quot;明天硬着头皮上&quot;，今天真的讲完了。把两篇论文的东西从头到尾过了一遍——主线、数据、结果、结论，该说的都说了。</p><p>讲完那一刻真挺爽的。之前悬着的那口气，总算吐出来了。之前汇报算法时的心慌还历历在目，这次准备得足，讲起来就稳多了。看来&quot;提前把可能被问到的点想一遍&quot;这招是管用的，以后继续保持。</p><h2 id="论文-又改了一遍" tabindex="-1">论文：又改了一遍 <a class="header-anchor" href="#论文-又改了一遍" aria-label="Permalink to &quot;论文：又改了一遍&quot;">​</a></h2><p>汇报完没歇着，<strong>论文又改了一遍</strong> 📝。</p><p>这轮改动主要干了两件事：</p><p><strong>一是去除 AI 的痕迹</strong> 🧹。之前那稿基本靠 AI 堆出来的，读着总有股&quot;AI 味&quot;——句式太规整、转折太生硬、有些话说得漂亮但没信息量。今天一段段抠，把那些空话换成人话，把那些&quot;正确的废话&quot;删掉。这活儿细碎但重要，稿子得读着像是自己写的，才拿得出手。</p><p><strong>二是重新看了一遍</strong>。有些地方上次改的时候没注意到的硬伤、前后对不上的表述，这轮重新过的时候揪出来了。改论文就是这样，每一遍都能挑出新毛病，所以才要一遍遍磨。</p><p><strong>图什么的也都改了</strong> 📊。配色、标注、图例、分辨率，能调的都调了一遍。图是论文的门面，糊弄不得——读者翻论文第一眼看的就是图。</p><h2 id="明天的任务-三件事" tabindex="-1">明天的任务：三件事 <a class="header-anchor" href="#明天的任务-三件事" aria-label="Permalink to &quot;明天的任务：三件事&quot;">​</a></h2><p>明天还有三件硬活：</p><ol><li><strong>通读一遍</strong>——从头到尾顺一遍，看还有没有读着别扭、逻辑断掉的地方。</li><li><strong>修改参考文献</strong>——格式统一、引用核对、该补的补上。这活儿枯燥但最容易被挑刺。</li><li><strong>讨论的逻辑结构</strong>——这块是最难啃的。讨论不是把结果复述一遍，得讲清楚&quot;所以呢&quot;、得跟已有研究对话、得说清局限和意义。逻辑结构理顺了，讨论才立得住。</li></ol><p><strong>完成了，才算修改完成</strong> 🎯。</p><h2 id="就这样-明天继续" tabindex="-1">就这样，明天继续 <a class="header-anchor" href="#就这样-明天继续" aria-label="Permalink to &quot;就这样，明天继续&quot;">​</a></h2><p>今天就到这儿。汇报过了、论文改了一轮、图也重做了，进度在往前往实里走。</p><p>明天把那三件事干完，这轮修改就能画句号了。加油 💪！</p>',19)])])}const c=a(s,[["render",n]]);export{u as __pageData,c as default};
